public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums[0]));
        return permutations;
    }

    // Recursive case: for each element in the input array,
    // generate all permutations of the remaining elements
    // and add the current element to each permutation
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, i + 1, nums.length);
        List<List<Integer>> subPermutations = permute(remaining);
        for (List<Integer> subPermutation : subPermutations) {
            subPermutation.add(0, current);
        }
        permutations.addAll(subPermutations);
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, i + 1, nums.length);
        List<List<Integer>> permutations = permute(remaining);
        for (List<Integer> permutation : permutations) {
            permutation.add(0, num);
            result.add(permutation);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    }
    permuteHelper(nums, new boolean[nums.length], 0, result);
    return result;
}

private void permuteHelper(int[] nums, boolean[] used, int current, List<List<Integer>> result) {
    if (current == nums.length) {
        result.add(getPermutation(nums, used));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            permuteHelper(nums, used, current + 1, result);
            used[i] = false;
        }
    }
}

private List<Integer> getPermutation(int[] nums, boolean[] used) {
    List<Integer> permutation = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            permutation.add(nums[i]);
        }
    }
    return permutation;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] newNums = new int[nums.length - 1];
        System.arraycopy(nums, 0, newNums, 0, i);
        System.arraycopy(nums, i + 1, newNums, i, nums.length - i - 1);
        List<List<Integer>> perm = permute(newNums);
        for (List<Integer> p : perm) {
            p.add(0, nums[i]);
            result.add(p);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, 0, result);
    return result;
}

private void backtrack(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.stream(nums).boxed().collect(Collectors.toList()));
    } else {
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            backtrack(nums, start + 1, result);
            swap(nums, start, i);
        }
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public int findLargestSubstring(List<String> strings) {
    // We will iteratively try all possible strings and their inverses, and keep track of the largest substring found so far.
    int largestSubstring = -1;
    for (String string : strings) {
        // Try the string and its inverse (with the characters in reverse order).
        if (isMaxSubstring(string, largestSubstring)) {
            largestSubstring = string.length();
        } else if (isMaxSubstring(string.reversed(), largestSubstring)) {
            largestSubstring = string.length();
        }
    }
    return largestSubstring;
}

private boolean isMaxSubstring(String string, int largestSubstring) {
    // Check if the string is a substring of any of the given strings.
    for (String otherString : strings) {
        if (otherString.contains(string)) {
            return true;
        }
    }
    // Check if the inverse of the string (with the characters in reverse order) is a substring of any of the given strings.
    String reversedString = new StringBuilder(string).reverse().toString();
    for (String otherString : strings) {
        if (otherString.contains(reversedString)) {
            return true;
        }
    }
    return false;
}

public static int findLargestSubstring(List<String> strings) {
    int max = 0;
    String maxStr = "";
    for (String str : strings) {
        if (str.length() > max) {
            max = str.length();
            maxStr = str;
        }
    }
    boolean found = false;
    for (String str : strings) {
        if (str.contains(maxStr) || str.contains(new StringBuilder(maxStr).reverse().toString())) {
            found = true;
            break;
        }
    }
    return found ? Math.max(max, maxStr.length()) : -1;
}

