public int findLargestSubstring(List<String> strings) {
    // Find the longest common substring
    int longestCommonSubstringLength = 1;
    for (int i = 1; i < strings.size(); i++) {
        for (int j = 0; j < strings.size() - i; j++) {
            String substr = strings.get(j).substring(0, i);
            int count = 0;
            for (int k = 0; k < strings.size(); k++) {
                if (strings.get(k).contains(substr)) {
                    count++;
                }
            }
            if (count > longestCommonSubstringLength) {
                longestCommonSubstringLength = count;
            }
        }
    }

    // Find the longest palindrome
    int longestPalindromeLength = 1;
    for (String s : strings) {
        if (s.length() > longestPalindromeLength) {
            longestPalindromeLength = s.length();
        }
    }

    // Return the maximum of the two
    return Math.max(longestCommonSubstringLength, longestPalindromeLength);
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                char[][] copyGrid = copyGrid(grid);
                dfs(copyGrid, i, j);
                if (!isValid(copyGrid, i, j)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static char[][] copyGrid(char[][] grid) {
    char[][] copyGrid = new char[grid.length][grid[0].length];
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            copyGrid[i][j] = grid[i][j];
        }
    }
    return copyGrid;
}

private static void dfs(char[][] grid, int x, int y) {
    if (isValid(grid, x, y) && grid[x][y] == '@') {
        grid[x][y] = '*';
        dfs(grid, x-1, y);
        dfs(grid, x+1, y);
        dfs(grid, x, y-1);
        dfs(grid, x, y+1);
    }
}

private static boolean isValid(char[][] grid, int x, int y) {
    return x >= 0 && x < grid.length && y >= 0 && y < grid[x].length;
}

public static int countOilDeposits(char[][] grid) {
  // Step 1: Initialize variables
  int numPlotPts = grid.length * grid[0].length; // total number of plot points
  int numDepsitPts = 0; // number of points with oil deposits
  boolean[][] visited = new boolean[numPlotPts][numPlotPts]; // keeps track of visited points

  // Step 2: Iterate through each point and check for oil deposits
  for (int i = 0; i < numPlotPts; i++) {
    for (int j = 0; j < numPlotPts; j++) {
      if (grid[i][j] == '@') {
        if (!visited[i][j]) {
          // hadn't visited this point yet - count as new oil deposit
          numDepsitPts++;
          // mark all points connected to this point as visited
          bfs(i, j, visited, grid);
        }
      }
    }
  }

  // Step 3: Return the number of distinct oil deposits
  return numDepsitPts;
}

public static void bfs(int i, int j, boolean[][] visited, char[][] grid) {
  Queue<int[]> queue = new LinkedList<int[]>();
  queue.add(new int[] {i, j});
  visited[i][j] = true;
  while (!queue.isEmpty()) {
    int[] point = queue.remove();
    int x = point[0], y = point[1];
    // add all 8-neighbor points to queue if they are connected to this point and not visited yet
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++) {
        int newX = x + dx;
        int newY = y + dy;
        if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[0].length && grid[newX][newY] == '@' && !visited[newX][newY]) {
          queue.add(new int[] {newX, newY});
          visited[newX][newY] = true;
        }
      }
    }
  }
}

