public static int maxRegions(int N) {
    // We know that a plane can be divided into two regions for N = 1 triangle.
    if (N == 1) {
        return 2;
    }
    // To determine the maximum number of regions for N = 2 triangles, we can reason as follows:
    // - Two triangles can intersect at a maximum of 2 corners.
    // - Each corner can be part of at most 2 regions (grouping of triangles).
    // Therefore, the maximum number of regions for N = 2 triangles is 2 x 2 = 4.
    if (N == 2) {
        return 4;
    }
    // For N > 2, we can keep splitting the plane into equal halves until all triangles are removed.
    // Each split can generate at most 4 regions. Therefore, the maximum number of regions is 4^N.
    return (int)Math.pow(4, N);
}

public static int maxRegions(int N) {
    int regions = 0;
    for (int i = 1; i <= N; i++) {
        regions += i;
    }
    return regions;
}

public static int maxRegions(int N) {
    // Initialize the maximum number of regions as 0
    int maxRegions = 0;

    // Iterate through all possible values of N
    for (int i = 0; i <= N; i++) {
        // For each value of N, calculate the number of regions by
        // dividing the number of triangles by 2 and rounding up
        int regions = (int) Math.ceil((double) N / 2);

        // If the current number of regions is greater than the previous value,
        // update the maximum number of regions
        if (regions > maxRegions) {
            maxRegions = regions;
        }
    }

    // Return the maximum number of regions
    return maxRegions;
}

