public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[] visited = new int[n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]] = 1;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1] && visited[path[2]] == 0) {
                visited[path[2]] = 1;
                queue.add(path[2]);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the input parameters are valid
    if (n <= 0 || start == null || start.length != 2 || end == null || end.length != 2 || paths == null || paths.length != n) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Initialize the visited matrix set to all false
    boolean[][] visitedMat = new boolean[n][n];

    // Find the starting location
    int startX = start[0];
    int startY = start[1];
    visitedMat[startX][startY] = true;

    // Find the ending location
    int endX = end[0];
    int endY = end[1];

    // Check if the starting and ending locations are the same
    if (startX == endX && startY == endY) {
        return "can be travelled";
    }

    // Loop through the matrix
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < n; y++) {
            // If the current location is the starting location, check if there is a path to the ending location
            if (x == startX && y == startY) {
                if (paths[x][y] == endX && paths[y][x] == endY) {
                    return "can be travelled";
                }
            }
            // If the current location is the ending location, check if there is a path to the starting location
            if (x == endX && y == endY) {
                if (paths[x][y] == startX && paths[y][x] == startY) {
                    return "can be travelled";
                }
            }
        }
    }

    // If no path to the ending location was found, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the given start and end coordinates are valid
    if (start[0] < 0 || start[1] < 0 || end[0] < 0 || end[1] < 0 ||
        start[0] >= n || start[1] >= n || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Initialize a 2D array to keep track of visited nodes
    boolean[][] visited = new boolean[n][n];

    // Mark the starting point as visited
    visited[start[0]][start[1]] = true;

    // Implement BFS to traverse the graph
    Queue<int[]> queue = new ArrayDeque<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // If the current point is the ending point, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Add all adjacent unvisited points to the queue
        for (int[] path : paths) {
            int x = current[0] + path[0];
            int y = current[1] + path[1];

            if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y]) {
                visited[x][y] = true;
                queue.offer(new int[] {x, y});
            }
        }
    }

    // If there is no path from the starting point to the ending point, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // 1. Validate input parameters
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    } else if (start.length != n || end.length != n || paths.length != n) {
        throw new IllegalArgumentException("Inconsistent input parameters");
    }

    // 2. Create a set to store all visited n-tersections
    Set<Integer> visited = new HashSet<Integer>();

    // 3. Add the starting n-tersection to the visited set
    visited.add(start[0]);

    // 4. Create a queue to store the n-tersections to be explored
    Queue<Integer> queue = new LinkedList<Integer>();
    queue.offer(start[0]);

    // 5. Explore all the n-tersections reachable from the starting n-tersection
    while (!queue.isEmpty()) {
        Integer current = queue.poll();
        visited.add(current);
        for (int i = 0; i < paths[current].length; i++) {
            Integer next = paths[current][i];
            if (!visited.contains(next)) {
                if (next.equals(end[0])) {
                    return "can be travelled";
                } else {
                    visited.add(next);
                    queue.offer(next);
                }
            }
        }
    }

    // 6. If the ending n-tersection is not visited, return "cannot be travelled"
    if (!visited.contains(end[0])) {
        return "cannot be travelled";
    }

    // 7. Otherwise, return "can be travelled"
    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();

    queue.add(start[0]);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();

        if (current == end[0]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            if (path[0] == current) {
                int neighbor = path[1];

                if (!visited[neighbor]) {
                    queue.add(neighbor);
                    visited[neighbor] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
	StringBuilder result = new StringBuilder();
	result.append("appx(");
	result.append(word1);
	result.append(", ");
	result.append(word2);
	result.append(") = ");

	// Calculate the intersection of the two words
	Set<Character> intersection = new HashSet<>(word1.length() + word2.length());
	for (int i = 0; i < word1.length(); i++) {
		Character letter1 = word1.charAt(i);
		for (int j = 0; j < word2.length(); j++) {
			Character letter2 = word2.charAt(j);
			if (letter1.equals(letter2)) {
				intersection.add(letter1);
				break;
			}
		}
	}

	// Calculate the approximated value by dividing the intersection size
	// by the sum of the lengths of the two words
	int numerator = intersection.size();
	int denominator = word1.length() + word2.length();
	result.append(numerator);
	result.append("/");
	result.append(denominator);

	return result.toString();
}

