public static String convertDatesToWeekdays(String date) {
    // Extract month, day, and year from the input date
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    // Get the century and year parts of the input date
    int century = year / 100;
    int yearInCentury = year % 100;

    // Get the weekday number for the specified date
    int weekdayNumber = (day + 2 * month + 3 * (month + 1) / 5 + year + year / 4 + century / 4 - 2 * century) % 7;

    // Return the weekday name for the corresponding weekday number
    switch (weekdayNumber) {
        case 0: return "Sunday";
        case 1: return "Monday";
        case 2: return "Tuesday";
        case 3: return "Wednesday";
        case 4: return "Thursday";
        case 5: return "Friday";
        case 6: return "Saturday";
        default: throw new IllegalArgumentException("Invalid weekday number: " + weekdayNumber);
    }
}

public static String convertDatesToWeekdays(String date) {
    String weekdays[] = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    int day = Integer.parseInt(date.substring(0, 2));
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date: " + date);
    }
    int month = Integer.parseInt(date.substring(3, 5));
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid date: " + date);
    }
    int year = Integer.parseInt(date.substring(6, 10));
    if (year < 1900 || year > LocalDate.now().getYear()) {
        throw new IllegalArgumentException("Invalid date: " + date);
    }

    LocalDateTime ldt = LocalDateTime.of(year, month, day, 0, 0);
    String weekday = weekdays[ldt.getDayOfWeek().getValue() - 1];

    return String.format("%s %d, %d is a %s", ldt.getMonth().toString(), ldt.getDayOfMonth(), ldt.getYear(), weekday);
}

