public static String convertDatesToWeekdays(String date) {
    String[] months = {
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December"
    };
    String[] daysOfWeek = {
        "Sunday",
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday"
    };

    int day = Integer.parseInt(date.substring(3, 5));
    int month = Integer.parseInt(date.substring(0, 2));
    int year = Integer.parseInt(date.substring(6, 10));

    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Calculate the timestamp since the epoch
    int epoch = 50;
    while (epoch < year) {
        epoch += 4;
        // Add a day for each leap year
        if (epoch % 100 != 0 && epoch % 4 == 0) {
            epoch++;
        }
    }

    // Calculate the day of the week
    int dayOfWeek = (epoch + (365 * (year - 1)) +
                    Math.floor((year - 1) / 4) -
                    Math.floor((year - 1) / 100) +
                    Math.floor((year - 1) / 400) +
                    (1 + (31 * (month - 1)) + (month / 2) + day) - 3)
                    % 7;

    return months[month - 1] + " " + day + ", " + year + " is a " + daysOfWeek[dayOfWeek];
}

