public double trimMean(int[] arr) {
    // Sort the input array in ascending order
    Arrays.sort(arr);

    // Calculate the quantiles of the array
    int lowerQuantile = (int) Math.ceil(arr.length * 0.05); // 5% of the elements
    int upperQuantile = (int) Math.floor(arr.length * 0.95); // 95% of the elements

    // Calculate the sum of the elements between the quantiles
    int sum = 0;
    for (int i = lowerQuantile; i <= upperQuantile; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the elements between the quantiles
    double mean = sum / (double) (upperQuantile - lowerQuantile);

    // Return the mean with the desired level of precision
    return Double.parseDouble(String.format("%.5f", mean));
}

public double trimMean(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("The input array is empty");
        }
        int[] trimmedArray = trimArray(arr, 0.05);
        return getMean(trimmedArray);
    }

private double getMean(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("The input array is empty");
        }
        double sum = 0;
        for (int i = 0; i < arr.length; i++) {
            sum += arr[i];
        }
        return sum / arr.length;
    }

private int[] trimArray(int[] arr, double percent) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("The input array is empty");
        }
        if (percent < 0 || percent > 1) {
            throw new IllegalArgumentException("Invalid trim percentage");
        }
        int startIndex = (int) Math.ceil(arr.length * percent);
        int endIndex = arr.length - startIndex - 1;
        int[] trimmedArray = new int[endIndex - startIndex + 1];
        for (int i = startIndex; i <= endIndex; i++) {
            trimmedArray[i - startIndex] = arr[i];
        }
        return trimmedArray;
    }

public double trimMean(int[] arr) {
    // Calculate the pruning threshold for both
    // the smallest and largest elements
    double smallestThreshold = 5.0 / 100.0 * arr.length;
    double largestThreshold = 5.0 / 100.0 * arr.length;

    // Initialize the arrays to store the trimmed elements
    int[] smallerElements = new int[arr.length - (int) smallestThreshold];
    int[] largerElements = new int[arr.length - (int) largestThreshold];

    // Iterate through the array and copy the elements into the
    // smaller and larger arrays, skipping over the smallest and
    // largest elements
    int smallerIndex = 0;
    int largerIndex = 0;
    for (int i = 0; i < arr.length; i++) {
        if (i < smallestThreshold) {
            smallerElements[smallerIndex++] = arr[i];
        } else if (i >= arr.length - largestThreshold) {
            largerElements[largerIndex++] = arr[i];
        }
    }

    // Calculate the mean of the smaller and larger arrays
    double smallerMean = mean(smallerElements);
    double largerMean = mean(largerElements);

    // Calculate the trimmed mean
    double trimmedMean = smallerMean + largerMean;
    trimmedMean /= 2.0;

    return trimmedMean;
}

private static double mean(int[] arr) {
    // Calculate the sum of the elements
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }

    // Calculate the average
    double mean = (double) sum / arr.length;

    return mean;
}

