    Arrays.sort(arr);

    // remove the smallest trimSize elements from the front and largest trimSize elements from the back
    int[] subArr = Arrays.copyOfRange(arr, trimSize, arr.length - trimSize);

    // calculate the mean of the remaining elements
    double sum = 0.0;
    for (int i = 0; i < subArr.length; i++) {
        sum += subArr[i];
    }
    double mean = sum / subArr.length;

    // return the mean with error within 10^-5
    return mean;
}

