    // Get the length of the array
    int length = arr.length;

    // Calculate the number of elements to remove from the start and end of the array
    int numElementsToRemove = (int) Math.round((length * 0.05));

    // Calculate the start and end indices of the array after removing the smallest and largest elements
    int startIndex = numElementsToRemove;
    int endIndex = length - numElementsToRemove - 1;

    // Initialize the sum of the remaining elements
    double sum = 0;

    // Iterate through the remaining elements and calculate the sum
    for (int i = startIndex; i <= endIndex; i++) {
        sum += arr[i];
    }

    // Return the mean of the remaining elements
    return sum / (endIndex - startIndex + 1);
}

public boolean canArrange(int[] arr, int k) {
    // Check if the input is valid
    if (arr == null || arr.length == 0 || k <= 1) {
        return false;
    }

    // Initialize a hash map to store the count of each number in the array
    Map<Integer, Integer> countMap = new HashMap<>();
    for (int num : arr) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    // Iterate over the hash map and check if the sum of each pair is divisible by k
    for (int num : countMap.keySet()) {
        int count = countMap.get(num);
        if (count > 0 && num % k == 0) {
            count--;
            if (count > 0) {
                int complement = (num / k) * k - num;
                if (countMap.containsKey(complement)) {
                    int complementCount = countMap.get(complement);
                    if (complementCount > 0) {
                        complementCount--;
                        if (complementCount == 0) {
                            countMap.remove(complement);
                        } else {
                            countMap.put(complement, complementCount);
                        }
                    }
                }
            }
        }
    }

    // If the hash map is empty, it means that the array can be divided into n/2 pairs such that the sum of each pair is divisible by k
    return countMap.isEmpty();
}

public boolean canArrange(int[] arr, int k) {
    // Check if the input array is valid
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    // Sort the input array in ascending order
    Arrays.sort(arr);

    // Loop through the array and find pairs that sum up to k
    for (int i = 0; i < arr.length / 2; i++) {
        int pairSum = arr[i] + arr[arr.length - 1 - i];
        if (pairSum % k != 0) {
            return false;
        }
    }

    // If all pairs sum up to k, the array can be divided into n/2 pairs
    return true;
}

