    for (int i = 0; i < n; i++) {
        pairs[i][0] = arr[i];
        pairs[i][1] = arr[i + n];
    }
    for (int i = 0; i < n; i++) {
        int sum = pairs[i][0] + pairs[i][1];
        if (sum % k != 0) {
            return false;
        }
    }
    return true;
}

