    Arrays.sort(arr);

    // Next, we divide the array into pairs using a sliding window of size 2
    for (int i = 0; i < arr.length - 1; i += 2) {
        int sum = arr[i] + arr[i + 1];
        if (sum % k != 0) {
            return false;
        }
    }

    // If we reach this point, it means that all pairs have a sum divisible by k
    return true;
}

