    int n = arr.length / 2;
    int[] sums = new int[n];
    for (int i = 0; i < n; i++) {
        sums[i] = arr[i] + arr[arr.length - i - 1];
    }
    for (int i = 0; i < n; i++) {
        if (sums[i] % k != 0) return false;
    }
    return true;
}

