    for (i in 0 until n) {
        if (hasApple[i]) {
            time += 2
        }
    }
    return time
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (visited[node]) continue;
        visited[node] = true;
        for (int neighbor : edges[node]) {
            if (!visited[neighbor] && dist[neighbor] > dist[node] + 1) {
                dist[neighbor] = dist[node] + 1;
                queue.offer(neighbor);
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += dist[i];
        }
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        dist[i] = Integer.MAX_VALUE;
        visited[i] = false;
    }
    dist[0] = 0;
    visited[0] = true;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < edges.length; j++) {
            int src = edges[j][0];
            int dst = edges[j][1];
            if (!visited[dst] && dist[src] + (hasApple[src] ? 2 : 1) < dist[dst]) {
                dist[dst] = dist[src] + (hasApple[src] ? 2 : 1);
            }
        }
    }
    return dist[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] costs = new int[n];
    Arrays.fill(costs, Integer.MAX_VALUE);
    costs[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < Math.min(edges.length, n); k++) {
                int neighbor = edges[k][j];
                if (hasApple[j]) {
                    costs[neighbor] = Math.min(costs[neighbor], costs[j] + 1);
                }
            }
        }
    }

    int totalCost = 0;
    for (int i = 1; i < n; i++) {
        totalCost += costs[i];
    }

    return totalCost;
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
      char smallest = 'z';
      for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) < smallest) {
          smallest = s.charAt(i);
        }
      }
      result += smallest;
      s = s.replace(smallest, '\0');

      char largest = 'A';
      for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) > largest) {
          largest = s.charAt(i);
        }
      }
      result += largest;
      s = s.replace(largest, '\0');
    }
    return result;
  }

public String sortString(String s) {
    String result = "";
    int[] pos = new int[26];
    for (int i = 0; i < s.length(); i++) {
        pos[s.charAt(i) - 'a']++;
    }
    for (int i = 0; i < s.length(); i++) {
        int min = findMin(pos);
        if (min != -1) {
            result += (char) (min + 'a');
            pos[min]--;
        }
    }
    for (int i = s.length() - 1; i >= 0; i--) {
        int max = findMax(pos);
        if (max != -1) {
            result += (char) (max + 'a');
            pos[max]--;
        }
    }
    return result;
}

private int findMin(int[] pos) {
    int min = -1;
    for (int i = 0; i < pos.length; i++) {
        if (pos[i] > 0 && (min == -1 || i < min)) {
            min = i;
        }
    }
    return min;
}

private int findMax(int[] pos) {
    int max = -1;
    for (int i = pos.length - 1; i >= 0; i--) {
        if (pos[i] > 0 && (max == -1 || i > max)) {
            max = i;
        }
    }
    return max;
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        // Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        s = s.substring(1);
        result += smallest;

        // Pick the smallest character from s which is greater than the last appended character to the result and append it
        if (s.length() > 0) {
            char smaller = s.charAt(s.length() - 1);
            if (smaller > smallest) {
                s = s.substring(0, s.length() - 1);
                result += smaller;
            }
        }

        // Pick the largest character from s and append it to the result
        char largest = s.charAt(s.length() - 1);
        s = s.substring(0, s.length() - 1);
        result += largest;

        // Pick the largest character from s which is smaller than the last appended character to the result and append it
        if (s.length() > 0) {
            char larger = s.charAt(s.length() - 1);
            if (larger < largest) {
                s = s.substring(0, s.length() - 1);
                result += larger;
            }
        }
    }
    return result;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    String result = "";
    // Step 1: Pick the smallest character from s and append it to the result.
    char smallest = s.charAt(0);
    result += smallest;
    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c > smallest) {
            smallest = c;
            result += smallest;
        }
    }
    // Step 3: Repeat step 2 until you cannot pick more characters.
    // ...
    // Step 4: Pick the largest character from s and append it to the result.
    char largest = s.charAt(s.length() - 1);
    result += largest;
    // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
    for (int i = s.length() - 2; i >= 0; i--) {
        char c = s.charAt(i);
        if (c < largest) {
            largest = c;
            result += largest;
        }
    }
    // Step 6: Repeat step 5 until you cannot pick more characters.
    // ...
    // Step 7: Repeat the steps from 1 to 6 until you pick all characters from s.
    // ...
    return result;
}

public String sortString(String s) {
    List<Character> chars = new ArrayList<>(s.length());
    for (char c : s.toCharArray()) {
        chars.add(c);
    }
    chars.sort(Comparator.naturalOrder());
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length() - 1; i++) {
        if (chars.get(i) < chars.get(i + 1)) {
            sb.append(chars.get(i));
        }
    }
    for (int i = s.length() - 1; i >= 0; i--) {
        if (chars.get(i) > chars.get(i - 1)) {
            sb.append(chars.get(i));
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    int avg = total / n;
    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i < n; i++) {
        if (sum1 + nums[i] <= avg) {
            sum1 += nums[i];
        } else {
            sum2 += nums[i];
        }
    }
    return sum1 == sum2;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int leftSum = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        leftSum += nums[i];
        if (leftSum == sum / 2) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    if (n % 2 == 1) {
        return false;
    }
    int totalSum = sum / 2;
    int currentSum = 0;
    int[] left = new int[n / 2];
    for (int i = 0; i < n / 2; i++) {
        currentSum += nums[i];
        left[i] = nums[i];
    }
    if (currentSum != totalSum) {
        return false;
    }
    int[] right = new int[n / 2];
    for (int i = n / 2; i < n; i++) {
        currentSum += nums[i];
        right[i - n / 2] = nums[i];
    }
    if (currentSum != totalSum) {
        return false;
    }
    return true;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length == 1) {
