}

public boolean splitArraySameAverage(int[] nums) {
    double sum = 0.0;
    for (int num : nums) {
        sum += num;
    }
    double average = sum / nums.length;

    double sum1 = 0.0;
    double sum2 = 0.0;
    for (int i = 0; i < nums.length; i++) {
        if (i == 0) {
            sum1 += nums[i];
        } else {
            sum2 += nums[i];
        }
    }

    return Math.abs(average - sum1 / nums.length) <= 1e-6 && Math.abs(average - sum2 / (nums.length - 1)) <= 1e-6;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 2] + cost[i], dp[i - 1] + cost[i]);
    }
    return dp[n - 1];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) {
        throw new IllegalArgumentException("Input array is empty");
    } else if (cost.length == 1) {
        return cost[0];
    } else {
        int[] dp = new int[cost.length];
        dp[0] = cost[0];
        dp[1] = cost[1];
        for (int i = 2; i < dp.length; i++) {
            dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
        }
        return Math.min(dp[dp.length-1], dp[dp.length-2]);
    }
}

public static int minCostClimbingStairs(int[] cost) {
    if (cost.length == 1) return cost[0];
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1] + Math.min(cost[0], cost[2]);
    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i], dp[i - 2] + cost[i]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    // Initialization
    int n = cost.length;
    int[] dp = new int[n];

    // Base case
    dp[0] = cost[0];
    dp[1] = cost[1];

    // DP
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    // Return
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) return 0;

    Map<String, Integer> morseMap = new HashMap<>();
    for (String word : words) {
        StringBuilder morseCode = new StringBuilder();
        for (char c : word.toCharArray()) {
            morseCode.append(getMorseCode(c));
        }
        String morse = morseCode.toString();
        if (!morseMap.containsKey(morse)) {
            morseMap.put(morse, 1);
        } else {
            morseMap.put(morse, morseMap.get(morse) + 1);
        }
    }

    return morseMap.values().size();
}

