    int leftCount = 0, rightCount = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftCount++;
        } else {
            rightCount++;
        }
    }
    int diff = Math.abs(leftCount - rightCount);
    return diff > 0 ? diff / 2 + (diff % 2) : 0;
}

