public int minOperations(int n) {
    int arr[] = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int count = 0;
    int sum = (2 * n) + 1;
    while (sum != n * (n + 1) / 2) {
        for (int i = 0; i < n; i++) {
            if (arr[i] != sum) {
                int x = (i - 1 + n) % n;
                int y = (i + 1) % n;
                count++;
                arr[x]--;
                arr[y]++;
                break;
            }
        }
        sum = 0;
        for (int i = 0; i < n; i++) {
            sum += arr[i];
        }
    }
    return count;
}

public int minOperations(int n) {
    int arr[] = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 2 * i + 1;
    }
    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        int target = (n - 1) / 2;
        if (arr[i] != target) {
