public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;
    int[] dp = new int[k+1];
    for (int i = 1; i <= k; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[1] = 1;
    dp[2] = 1;
    for (int i = 3; i <= k; i++) {
        for (int j = 1; j <= k/i; j++) {
            dp[i] = Math.min(dp[i], dp[i-j] + 1);
        }
    }
    return dp[k];
}

