public String makeGood(String s) {
    // Initialize a StringBuilder to store the final "good" string
    StringBuilder goodStr = new StringBuilder();

    // Iterate through the input string
    for (int i = 0; i < s.length(); i++) {
        // Check if the current character is a lowercase letter
        if (Character.isLowerCase(s.charAt(i))) {
            // Check if the corresponding uppercase letter does not exist in the string
            if (i + 1 < s.length() && s.charAt(i + 1) == Character.toUpperCase(s.charAt(i))) {
                // If the uppercase letter exists, skip the current character
                continue;
            }
        }
        // If the current character is not a lowercase letter or the corresponding uppercase letter does not exist, add it to the final string
        goodStr.append(s.charAt(i));
    }

    // Return the final "good" string
    return goodStr.toString();
}

