public String makeGood(String s) {
    // Edge case: If the string is empty, return it
    if (s.length() == 0) {
        return s;
    }

    // Create a StringBuilder to store the cleaned string
    StringBuilder cleaned = new StringBuilder();

    // Iterate through each character in the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character and the previous character
        char current = s.charAt(i);
        char previous = (i > 0) ? s.charAt(i - 1) : Character.MIN_VALUE;

        // Check if the current character is the uppercase equivalent of the previous character
        if (current != Character.toUpperCase(previous)) {
            // If not, add the current character to the cleaned string
            cleaned.append(current);
        }
    }

    // Return the cleaned string
    return cleaned.toString();
}

public String makeGood(String s) {
    // Check if the string is empty
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Initialize a StringBuilder to store the final good string
    StringBuilder goodString = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < s.length(); i++) {
        // Check if the current character is an uppercase letter
        if (Character.isUpperCase(s.charAt(i))) {
            // If the current character is an uppercase letter, check if the previous character is the corresponding lowercase letter
            if (i > 0 && s.charAt(i - 1) == Character.toLowerCase(s.charAt(i))) {
                // If the previous character is the corresponding lowercase letter, remove both characters from the final good string
                goodString.delete(i - 1, i + 1);
                // Decrement the index to check the new character at the current position
                i--;
            } else {
                // If the current character is an uppercase letter and there is no previous lowercase letter, add it to the final good string
                goodString.append(s.charAt(i));
            }
        } else {
            // If the current character is a lowercase letter, add it to the final good string
            goodString.append(s.charAt(i));
        }
    }

    // Return the final good string
    return goodString.toString();
}

