    int[] dp = new int[n + 1];
    ArrayList<String> substrings = new ArrayList<>();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            if (j == n || s.charAt(i) != s.charAt(j)) {
                dp[i + 1] = Math.max(dp[i + 1], dp[j] + 1);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            if (dp[i + 1] == dp[j] && substrings.contains(s.substring(i, j))) {
                dp[i + 1]--;
            }
            if (dp[i + 1] > 0) {
                substrings.add(s.substring(i, j));
            }
        }
    }

    return dp[n];
}

