public String getSmallestString(int n, int k) {
    // Calculate the average value of a string of length n
    int avgVal = k / n;

    // Calculate the remainder of the division between k and n
    int rem = k % n;

    // Initialize the string to the average value
    String smallestString = new String(new char[n]).replace("\0", String.valueOf(avgVal));

    // Add the remainder to the first position in the string
    smallestString = smallestString.substring(0, rem) + String.valueOf((char) (avgVal + 1)) + smallestString.substring(rem);

    // Return the smallest string
    return smallestString;
}

