private static boolean isSteppingNumber(int num) {
    // if the number is a single digit, it is a stepping number
    if (num < 10) {
        return true;
    }

    // if the number is greater than 10, check if each digit is either one more or one less than the adjacent digit
    while (num > 0) {
        int digit = num % 10;
        num /= 10;

        // if the current digit is not one more or one less than the adjacent digit, the number is not a stepping number
        if (digit != num % 10 - 1 && digit != num % 10 + 1) {
            return false;
        }
    }

    return true;
}

