private static int helper(int[][] mat, int i, int j) {
    int longestLine = 0;
    for (int k = 0; k < mat[0].length; k++) {
        // Check horizontal line
        if (mat[i][k] == 1) {
            longestLine = Math.max(longestLine, helper(mat, i, k));
        }
        // Check vertical line
        if (mat[k][j] == 1) {
            longestLine = Math.max(longestLine, helper(mat, k, j));
        }
        // Check diagonal line
        if (i + k < mat.length && j + k < mat[0].length && mat[i + k][j + k] == 1) {
            longestLine = Math.max(longestLine, helper(mat, i + k, j + k));
        }
        // Check anti-diagonal line
        if (i - k >= 0 && j - k >= 0 && mat[i - k][j - k] == 1) {
            longestLine = Math.max(longestLine, helper(mat, i - k, j - k));
        }
    }
    return longestLine + 1;
}

