    // Convert the input integer to a string
    String nStr = Integer.toString(n);

    // Create a new string to store the output
    StringBuilder sb = new StringBuilder();

    // Loop through the characters of the input string
    for (int i = 0; i < nStr.length(); i++) {
        // If the character is a digit, append it to the output string
        if (Character.isDigit(nStr.charAt(i))) {
            sb.append(nStr.charAt(i));
        }
        // If the character is not a digit, append a dot as a thousand separator
        else {
            sb.append(".");
        }
    }

    // Remove the trailing dot
    sb.deleteCharAt(sb.length() - 1);

    // Return the output string
    return sb.toString();
}

