            if (i == j) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = 0;
            }
        }
    }
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i < n - len; i++) {
            int j = i + len - 1;
            if (isSquare(A[i] + A[j])) {
                for (int k = i + 1; k <= j; k++) {
