  int currentArea = 0;
  int[] heightStack = new int[heights.length];
  int stackTop = -1;

  for (int i = 0; i < heights.length; i++) {
    if (stackTop == -1 || heights[i] >= heightStack[stackTop]) {
      heightStack[++stackTop] = heights[i];
    } else {
      while (stackTop != -1 && heights[i] < heightStack[stackTop]) {
        currentArea = heightStack[stackTop] * (i - stackTop);
        if (currentArea > largestArea) {
          largestArea = currentArea;
        }
        i -= heightStack[stackTop--];
      }
      heightStack[++stackTop] = heights[i];
    }
  }

  while (stackTop != -1) {
    currentArea = heightStack[stackTop] * (heights.length - stackTop);
    if (currentArea > largestArea) {
      largestArea = currentArea;
    }
    stackTop--;
  }

  return largestArea;
}

