    int[] digits = getDigits(n);

    // Sort the digits
    Arrays.sort(digits);

    // Check if the sorted digits are the same as the original digits
    if (Arrays.equals(digits, getDigits(n))) {
        return -1;
    }

    // If not, return the smallest rearranged integer greater than n
    return findSmallestInteger(digits, n);
}

private static int findSmallestInteger(int[] digits, int n) {
    boolean sameDigits = true;
    int i = 0;
    while (i < digits.length) {
        if (digits[i] != n % 10) {
            sameDigits = false;
            break;
        }
        i++;
    }

    if (sameDigits) {
        return -1;
    }

    StringBuilder sb = new StringBuilder();
    for (int digit : digits) {
        sb.append(digit);
    }
    return Integer.parseInt(sb.toString());
}

private static int[] getDigits(int n) {
    String str = String.valueOf(n);
    int[] digits = new int[str.length()];
    for (int i = 0; i < str.length(); i++) {
        digits[i] = Character.getNumericValue(str.charAt(i));
    }
    return digits;
}

