        if (i == n) {
            result.add(i);
        } else {
            int index = (int) Math.round(i * Math.log10(n));
            if (index >= 0 && index < result.size()) {
                List<Integer> subList = result.subList(0, (int) Math.min(result.size(), index + 1));
                if (subList.stream().noneMatch(j -> j > i)) {
                    result.add(i);
                }
            } else {
                result.add(i);
            }
        }
    }

    return result;
}

