public static int minPerfectSquareSum(int n) {
    // initialize variables
    int minSquares = 0;
    int currentSquare = 1;
    int currentSum = currentSquare;

    // loop until we reach the target sum or exceed it
    while (currentSum <= n) {
        // check if the current sum is a perfect square
        if (isPerfectSquare(currentSum)) {
            // increment the number of squares
            minSquares++;
        }

        // move to the next perfect square
        currentSquare = nextPerfectSquare(currentSquare);
        currentSum += currentSquare;
    }

    // return the minimum number of squares
    return minSquares;
}

private static boolean isPerfectSquare(int n) {
    // generate a list of perfect squares up to the target number
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            perfectSquares.add(i);
        }
    }

    // check if the target number is in the list of perfect squares
    return perfectSquares.contains(n);
}

private static int nextPerfectSquare(int n) {
